---@class WelfareTabToggleLeft
local WelfareTabToggleLeft = Class("WelfareTabToggleLeft", CommonTabToggleLeft)

--region lifecycle
---@override
function WelfareTabToggleLeft:__init()
    self.super.__init(self)
    self._timer = nil
end

---@override
function WelfareTabToggleLeft:__delete()
    self.super.__delete(self)
    self._timer = nil
end

---@override
function WelfareTabToggleLeft:Start()
    self:StartTimer()
end

---@override
function WelfareTabToggleLeft:OnDestroy()
    -- 关闭定时器
    TimerModule.Instance:RemoveTimer(Constants.TimerName.WelfareTabToggleLeftTimer)
    for k, v in pairs(self.togglesData) do
        if v.dojo then
            local data = v.dojo
            if not isNull(data.redPointStrNode) then
                GameUtils.RemoveRedPointCallBack(data.redPointStrNode)
            end
            if not isNull(data.redNode) and not string.isEmpty(data.redNode) then
                print(data.redNode)
                GameUtils.RemoveRedPointCallBack(data.redNode)
            end
        else
            if not isNull(v.redPointStrNode) then
                GameUtils.RemoveRedPointCallBack(v.redPointStrNode)
            end
            if not isNull(v.redNode) and not string.isEmpty(v.redNode) then
                print(v.redNode)
                GameUtils.RemoveRedPointCallBack(v.redNode)
            end
        end
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
