--region inheritance
---@override
function WelfareTabToggleLeft:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(node1)
    local node = GetLuaBehaviour(cell.gameObject, nodeBehaviourPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local isSelected = index == self.selectIndex
        node.Env:FreshBaseUI({ dojo = self.togglesData[index + 1].dojo, isSelected = isSelected })
        node.Env:FreshIcon(self.togglesData[index + 1].dojo.icon)

        -- 选中状态
        node.Env:FreshSelectStatus(isSelected)
        node.Env:SetCallBack(function()
            --点击回调
            if index ~= self.selectIndex then
                --屏蔽掉重复点击当前选择的toggle
                local funcResult = self.togglesData[index + 1].func()
                if funcResult == 0 then
                    --选中失败时返回0，不切换选中状态
                    return--选中失败，直接返回
                end
                --成功选中后才会切换选中状态
                node.Env:FreshSelectStatus(true)
                node.Env:FreshBaseUI({ dojo = self.togglesData[index + 1].dojo, isSelected = true })
                node.Env:PlayAnimation()
                local preNodeGo = self.ListView:GetShownItemByItemIndex(self.selectIndex)
                if preNodeGo then
                    local preNode = GetLuaBehaviour(preNodeGo.gameObject, nodeBehaviourPath)
                    preNode.Env:FreshSelectStatus(false)
                    preNode.Env:FreshBaseUI({ dojo = self.togglesData[self.selectIndex + 1].dojo, isSelected = false })
                end
                self.selectIndex = index
            end
        end)
    end

    return cell
end
--endregion inheritance

--region public
---刷新指定cell
---@param index number 列表序号(从1开始)
function WelfareTabToggleLeft:RefreshCellByIndex(index)
    local go = self.ListView:GetShownItemByItemIndex(index - 1)
    if not isNull(go) then
        local scr = CfUtils.GetLuaScr(go, nodeBehaviourPath)
        scr:FreshBaseUI({ dojo = self.togglesData[index].dojo, isSelected = self.selectIndex == index - 1 })
    end
end
--endregion public

--region private
---开启定时器
function WelfareTabToggleLeft:StartTimer()
    TimerModule.Instance:AddTimer(Constants.TimerName.WelfareTabToggleLeftTimer, 0, 1, function()
        for i, data in ipairs(self.togglesData) do
            self:RefreshCellByIndex(i)
        end
    end)
end
--endregion private

return WelfareTabToggleLeft